import{_ as s,o as r,c as o,j as e,a as t}from"./chunks/framework.CZTQpGgQ.js";const m=JSON.parse('{"title":"第二十三届农交会“品牌之夜”活动在杭州举办2026-11-13","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"第二十三届农交会“品牌之夜”活动在杭州举办2026-11-13","date":"2026-11-13T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202611/t20261119_6489584.htm","summary":"本网讯\\n11月12日晚，第二十三届中国国际农产品交易会“品牌之夜”活动在杭州广播电视台举办。活动以“统筹发展科技农业、绿色农业、质量农业、品牌农业”为主线，讲述品牌故事，展示品牌形象，激发消费活力。\\n活动设置科技农业、绿色农业、质量农业、品牌农业四个篇章。科技篇章以洛川苹果、湛江金鲳鱼为案例，讲述科技如何为品牌提供支撑。绿色篇章以精河枸杞、苏州大米为案例，讲述绿色如何为品牌擦亮发展底色。...\\n","contentHash":"69395b58b0550d3525dfa9e8cd87068a","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-11-13-第二十三届农交会-品牌之夜-活动在杭州举办.md","filePath":"policies/2026-11-13-第二十三届农交会-品牌之夜-活动在杭州举办.md"}'),l={name:"policies/2026-11-13-第二十三届农交会-品牌之夜-活动在杭州举办.md"};function n(_,a,c,i,d,p){return r(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"第二十三届农交会-品牌之夜-活动在杭州举办2026-11-13",tabindex:"-1"},[t("第二十三届农交会“品牌之夜”活动在杭州举办2026-11-13 "),e("a",{class:"header-anchor",href:"#第二十三届农交会-品牌之夜-活动在杭州举办2026-11-13","aria-label":'Permalink to "第二十三届农交会“品牌之夜”活动在杭州举办2026-11-13"'},"​")],-1),e("blockquote",null,[e("p",null,[t("来源: "),e("a",{href:"https://scs.moa.gov.cn/gzdt/202611/t20261119_6489584.htm",target:"_blank",rel:"noreferrer"},"农业农村部市场与信息化司"),e("br"),t(" 日期: 2026-11-13 摘要: 本网讯 11月12日晚，第二十三届中国国际农产品交易会“品牌之夜”活动在杭州广播电视台举办。活动以“统筹发展科技农业、绿色农业、质量农业、品牌农业”为主线，讲述品牌故事，展示品牌形象，激发消费活力。 活动设置科技农业、绿色农业、质量农业、品牌农业四个篇章。科技篇章以洛川苹果、湛江金鲳鱼为案例，讲述科技如何为品牌提供支撑。绿色篇章以精河枸杞、苏州大米为案例，讲述绿色如何为品牌擦亮发展底色。...")])],-1),e("p",null,[e("a",{href:"https://scs.moa.gov.cn/gzdt/202611/t20261119_6489584.htm",target:"_blank",rel:"noreferrer"},"阅读原文")],-1)])])}const h=s(l,[["render",n]]);export{m as __pageData,h as default};
